public boolean close(final String id) throws IOException {
    Preconditions.checkNotNull(id, "null id");

    final Pair<WindowedTimeSeries, ?> pair = this.timeSeriess.remove(id);
    if (pair != null) {
      pair.first.close();
      return true;
    }

    return false;
  }
